 <section class="tb-screen" data-screen-panel="confirmation"><div class="tb-card"><div class="tb-confirm"><div class="tb-checkmark"><i class="fas fa-check"></i></div><h2 class="fw-bold">Time Blocks Created Successfully!</h2><p class="text-muted">The validated periods were saved and are ready for connected scheduling modules.</p><div class="tb-ref my-3" id="confirmRef">No generated set yet</div><div class="tb-preview-summary text-start my-3"><div class="tb-mini"><small>Set Name</small><strong id="confirmName">—</strong></div><div class="tb-mini"><small>Blocks Created</small><strong id="confirmCount">0</strong></div><div class="tb-mini"><small>Status</small><strong id="confirmStatus">—</strong></div><div class="tb-mini"><small>Validation</small><strong class="text-success"><i class="fas fa-circle-check me-1"></i>Passed</strong></div></div><div class="d-flex gap-2 justify-content-center flex-wrap"><button class="btn btn-primary" data-go="manage"><i class="fas fa-table-list me-1"></i>View Time Blocks</button><button class="btn btn-outline-primary" data-go="configure"><i class="fas fa-plus me-1"></i>Create Another Set</button><button class="btn btn-outline-secondary" data-go="connected"><i class="fas fa-share-nodes me-1"></i>Connected Modules</button></div></div></div></section>

