 <section class="tb-screen" data-screen-panel="manage"><div class="tb-card"><div class="tb-card-head"><h2><span class="tb-title-icon"><i class="fas fa-list-check"></i></span>View / Manage Time Blocks</h2><div class="d-flex gap-2 no-print"><button class="btn btn-outline-primary btn-sm" id="manageExport"><i class="fas fa-download me-1"></i>Export</button><button class="btn btn-outline-secondary btn-sm" id="manageHistory"><i class="fas fa-clock-rotate-left me-1"></i>History</button><button class="btn btn-primary btn-sm" data-go="single"><i class="fas fa-plus me-1"></i>Create Block</button></div></div><div class="tb-card-body"><div class="tb-note mb-3"><i class="fas fa-shield-halved me-2"></i>Blocks already used by schedules cannot be deleted. Deactivation keeps references and audit history intact; activation runs overlap checks again.</div><div class="tb-toolbar mb-3"><div class="tb-search"><i class="fas fa-magnifying-glass"></i><input id="manageSearch" class="form-control" placeholder="Search blocks..."></div><select id="manageCategory" class="form-select"><option value="">All categories</option><option>Regular</option><option>Custom</option><option>Exam-specific</option><option>Break</option></select><select id="manageStatus" class="form-select"><option value="">All statuses</option><option value="1">Active</option><option value="0">Inactive</option></select></div><div class="table-responsive"><table class="table tb-table mb-0"><thead><tr><th>#</th><th>Code / Label</th><th>Period</th><th>Category</th><th>Set</th><th>Status</th><th>Usage</th><th class="text-end">Actions</th></tr></thead><tbody id="manageBody"></tbody></table></div><div class="tb-action-row"><button class="btn btn-outline-secondary" data-go="dashboard"><i class="fas fa-arrow-left me-1"></i>Dashboard</button><button class="btn btn-outline-primary" data-go="connected"><i class="fas fa-arrow-right me-1"></i>How Blocks Are Used</button></div></div></div></section>

 <!-- 7 Connected -->
 <section class="tb-screen" data-screen-panel="connected"><div class="tb-card"><div class="tb-card-head"><h2><span class="tb-title-icon"><i class="fas fa-share-nodes"></i></span>Approved Blocks in Other Modules</h2><span class="tb-pill ready"><i class="fas fa-circle-check"></i>Shared scheduling data</span></div><div class="tb-card-body"><div class="tb-note mb-3"><i class="fas fa-database me-2"></i>This subsystem defines valid periods only. Teachers, rooms, sections, and classes are assigned by their own connected modules using the same records.</div><div class="tb-connect" id="consumerGrid"></div><div class="d-flex align-items-center justify-content-center gap-3 flex-wrap my-4 text-center"><span class="tb-pill regular fs-6"><i class="fas fa-clock"></i>Approved Time Blocks</span><i class="fas fa-arrow-right tb-arrow"></i><span class="tb-pill ready fs-6"><i class="fas fa-shield-halved"></i>Conflict Validation</span><i class="fas fa-arrow-right tb-arrow"></i><span class="tb-pill exam-specific fs-6"><i class="fas fa-calendar-check"></i>Published Schedule</span></div><div class="tb-action-row"><button class="btn btn-outline-secondary" data-go="manage"><i class="fas fa-arrow-left me-1"></i>Manage Blocks</button><a class="btn btn-primary" href="<?= BASE_URL ?>/modules/scheduling/pages/teacher-schedule-mapping.php"><i class="fas fa-chalkboard-user me-1"></i>Open Teacher Mapping</a></div></div></div></section>
</div>

<div class="modal fade" id="tbHistoryModal" tabindex="-1" aria-hidden="true"><div class="modal-dialog modal-lg modal-dialog-scrollable"><div class="modal-content"><div class="modal-header"><h5 class="modal-title"><i class="fas fa-clock-rotate-left text-primary me-2"></i>Time Block History</h5><button type="button" class="btn-close" data-bs-dismiss="modal"></button></div><div class="modal-body" id="historyBody"></div><div class="modal-footer"><button class="btn btn-secondary" data-bs-dismiss="modal">Close</button></div></div></div></div>

<script>
(()=>{'use strict';const BASE='<?= BASE_URL ?>',API=BASE+'/api/scheduling/time-blocks.php';let state={blocks:[],summary:{},sets:[],history:[],consumers:[],preview:null,previewPayload:null,lastSet:null};const $=id=>document.getElementById(id);const esc=v=>String(v??'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');
const routes={section:BASE+'/modules/scheduling/pages/section-assignment-tool.php',teacher:BASE+'/modules/scheduling/pages/teacher-schedule-mapping.php',room:BASE+'/modules/scheduling/pages/room-availability-checker.php',special:BASE+'/modules/scheduling/pages/special-class-scheduler.php',exam:BASE+'/modules/scheduling/pages/exam-timetable-generator.php',conflict:BASE+'/modules/scheduling/pages/conflict-checker.php'};
function alertMsg(msg,kind='info'){const b=$('tbAlert');b.className='alert mt-3 alert-'+kind;$('tbAlertIcon').className='fas '+(kind==='success'?'fa-circle-check':kind==='danger'?'fa-triangle-exclamation':'fa-circle-info')+' me-2';$('tbAlertText').textContent=msg;b.classList.remove('d-none');window.scrollTo({top:0,behavior:'smooth'});}function hideAlert(){$('tbAlert').classList.add('d-none');}
async function req(body=null){const res=await fetch(body?API:API+'?action=dashboard',{method:body?'POST':'GET',credentials:'same-origin',headers:{Accept:'application/json','Content-Type':'application/json'},body:body?JSON.stringify(body):undefined});const data=await res.json().catch(()=>({ok:false,error:'The server returned an unreadable response.'}));if(!res.ok||!data.ok)throw new Error(data.error||'Request failed.');return data;}
function go(name){document.querySelectorAll('.tb-screen').forEach(x=>x.classList.toggle('active',x.dataset.screenPanel===name));document.querySelectorAll('.tb-step').forEach((x,i)=>{x.classList.toggle('active',x.dataset.screen===name);x.classList.toggle('done',i<[...document.querySelectorAll('.tb-step')].findIndex(s=>s.dataset.screen===name));});if(name==='manage')renderManage();if(name==='connected')renderConsumers();hideAlert();window.scrollTo({top:0,behavior:'smooth'});}
function fmtTime(t){if(!t)return'—';const [h,m]=t.slice(0,5).split(':').map(Number),p=h>=12?'PM':'AM';return `${h%12||12}:${String(m).padStart(2,'0')} ${p}`;}function duration(n){if(!n)return'—';return n%60?`${Math.floor(n/60)?Math.floor(n/60)+' hr ':''}${n%60} min`:`${n/60} hr`;}
function statusPill(b){return `<span class="tb-pill ${Number(b.is_active)===1?'active':'inactive'}"><i class="fas ${Number(b.is_active)===1?'fa-circle-check':'fa-circle-pause'}"></i>${Number(b.is_active)===1?'Active':'Inactive'}</span>`;}function catPill(c){return `<span class="tb-pill ${String(c).toLowerCase().replace(/ /g,'-')}">${esc(c)}</span>`;}
function filtered(search,type,status,category){const q=(search||'').toLowerCase();return state.blocks.filter(b=>(!q||[b.code,b.label,b.start_time,b.end_time,b.set_name].join(' ').toLowerCase().includes(q))&&(!type||b.block_type===type)&&(!status||String(b.is_active)===status)&&(!category||b.category===category));}
function actionButtons(b,full=false){return `<div class="d-inline-flex gap-1"><button class="btn btn-sm btn-outline-primary" data-edit="${b.id}" title="Edit"><i class="fas fa-pen"></i>${full?' Edit':''}</button><button class="btn btn-sm btn-outline-${Number(b.is_active)===1?'warning':'success'}" data-toggle="${b.id}" title="${Number(b.is_active)===1?'Deactivate':'Activate'}"><i class="fas fa-${Number(b.is_active)===1?'pause':'play'}"></i></button><button class="btn btn-sm btn-outline-danger" data-delete="${b.id}" ${Number(b.usage_count)>0?'disabled title="Referenced by schedules"':'title="Delete unused block"'}><i class="fas fa-trash-can"></i></button></div>`;}
function renderDashboard(){const s=state.summary;$('statTotal').textContent=s.total||0;$('statActive').textContent=s.active||0;$('statInactive').textContent=s.inactive||0;$('statExam').textContent=s.exam||0;$('statUsed').textContent=s.in_use||0;const rows=filtered($('dashSearch').value,$('dashType').value,$('dashStatus').value,'');$('dashBody').innerHTML=rows.length?rows.slice(0,8).map(b=>`<tr><td><span class="tb-code">${esc(b.code)}</span><div class="text-muted small">${esc(b.label)}</div></td><td>${fmtTime(b.start_time)} – ${fmtTime(b.end_time)}</td><td>${catPill(b.category)}</td><td>${duration(Number(b.duration_minutes))}</td><td>${statusPill(b)}</td><td>${Number(b.usage_count)||'—'}</td><td class="text-end">${actionButtons(b)}</td></tr>`).join(''):`<tr><td colspan="7" class="tb-empty"><i class="fas fa-clock fa-2x d-block mb-2"></i>No blocks match the filters.</td></tr>`;$('recentSets').innerHTML=state.sets.length?state.sets.slice(0,4).map(s=>`<div class="tb-set-row"><div><strong>${esc(s.name)}</strong><div class="small text-muted">${esc(s.reference_no)} · ${s.block_count} blocks</div></div><span class="tb-pill ${s.status==='Active'?'active':'inactive'}">${esc(s.status)}</span></div>`).join(''):'<div class="text-muted small">No generated sets yet.</div>';bindRowActions($('dashBody'));}
function renderManage(){const rows=filtered($('manageSearch').value,'',$('manageStatus').value,$('manageCategory').value);$('manageBody').innerHTML=rows.length?rows.map((b,i)=>`<tr><td>${i+1}</td><td><span class="tb-code">${esc(b.code)}</span><div class="text-muted small">${esc(b.label)}</div></td><td>${fmtTime(b.start_time)} – ${fmtTime(b.end_time)}<div class="small text-muted">${duration(Number(b.duration_minutes))}</div></td><td>${catPill(b.category)}</td><td>${b.set_reference?`<strong>${esc(b.set_reference)}</strong><div class="small text-muted">${esc(b.set_name)}</div>`:'<span class="text-muted">Manual</span>'}</td><td>${statusPill(b)}</td><td><span class="tb-pill ${Number(b.usage_count)>0?'regular':'inactive'}"><i class="fas fa-link"></i>${Number(b.usage_count)}</span></td><td class="text-end">${actionButtons(b,true)}</td></tr>`).join(''):`<tr><td colspan="8" class="tb-empty">No blocks match the filters.</td></tr>`;bindRowActions($('manageBody'));}
function renderConsumers(){$('consumerGrid').innerHTML=state.consumers.map(c=>`<a href="${routes[c.key]||'#'}" class="tb-connect-card text-decoration-none text-reset"><i class="fas ${esc(c.icon)}"></i><div><h3>${esc(c.name)} <i class="fas fa-arrow-up-right-from-square ms-1 small text-primary"></i></h3><p>${esc(c.use)}</p></div></a>`).join('');}
function renderHistory(){$('historyBody').innerHTML=state.history.length?state.history.map(h=>`<div class="tb-history-item"><strong><i class="fas fa-circle-dot text-primary me-1"></i>${esc(h.action)} ${h.block_code?'· '+esc(h.block_code):h.set_reference?'· '+esc(h.set_reference):''}</strong><p>${esc(h.detail)}</p><small>${esc(h.changed_by_name)} · ${new Date(String(h.created_at).replace(' ','T')).toLocaleString()}</small></div>`).join(''):'<div class="tb-empty">No history yet.</div>';bootstrap.Modal.getOrCreateInstance($('tbHistoryModal')).show();}
async function load(show=false){try{const d=await req();state={...state,...d};renderDashboard();renderManage();renderConsumers();if(show)alertMsg('Time block data refreshed.','success');}catch(e){alertMsg(e.message,'danger');}}
function singlePayload(action){const id=Number($('editId').value)||undefined;return{action,id,code:$('singleCode').value.trim(),label:$('singleLabel').value.trim(),start_time:$('singleStart').value,end_time:$('singleEnd').value,block_type:$('singleType').value,is_active:$('singleActive').checked?1:0,operating_start:$('singleOpStart').value,operating_end:$('singleOpEnd').value};}
function updateDuration(){const s=$('singleStart').value,e=$('singleEnd').value;if(!s||!e){$('singleDuration').innerHTML='<i class="fas fa-hourglass-half me-2"></i>—';return;}const [sh,sm]=s.split(':').map(Number),[eh,em]=e.split(':').map(Number),n=eh*60+em-sh*60-sm;$('singleDuration').innerHTML=`<i class="fas fa-hourglass-half me-2"></i>${n>0?duration(n):'Invalid range'}`;}
function resetSingle(){['editId','singleCode','singleLabel','singleStart','singleEnd'].forEach(id=>$(id).value='');$('singleType').value='Class';$('singleActive').checked=true;$('singleOpStart').value='06:00';$('singleOpEnd').value='22:00';$('singleTitle').textContent='Create Single Time Block';$('singleValidation').className='tb-note';$('singleValidation').innerHTML='<i class="fas fa-circle-info me-1"></i>Enter the block details, then run validation before saving.';updateDuration();}
async function validateSingle(){try{const d=await req(singlePayload('validate_single'));$('singleValidation').className='tb-validation';$('singleValidation').innerHTML=`<strong><i class="fas fa-circle-check me-1"></i>All checks passed</strong>${d.checks.map(x=>`<div class="tb-check"><i class="fas fa-check"></i><span>${esc(x)}</span></div>`).join('')}`;return true;}catch(e){$('singleValidation').className='tb-validation error';$('singleValidation').innerHTML=`<strong><i class="fas fa-triangle-exclamation me-1"></i>Validation failed</strong><div class="tb-check"><i class="fas fa-xmark"></i><span>${esc(e.message)}</span></div>`;return false;}}
async function saveSingle(){const ok=await validateSingle();if(!ok)return;const body=singlePayload($('editId').value?'update':'create');try{const d=await req(body);resetSingle();await load();go('manage');alertMsg(d.message,'success');}catch(e){alertMsg(e.message,'danger');}}
function setPayload(action){return{action,set_name:$('setName').value.trim(),block_type:$('setType').value,start_time:$('setStart').value,end_time:$('setEnd').value,interval_minutes:Number($('setInterval').value),include_break:$('includeBreak').checked?1:0,break_start:$('breakStart').value,break_end:$('breakEnd').value,break_label:$('breakLabel').value.trim(),activate:$('setActivate').checked?1:0};}
function renderPreview(){const p=state.preview,c=p.config;$('previewName').textContent=c.set_name;$('previewRange').textContent=fmtTime(c.start_time)+' – '+fmtTime(c.end_time);$('previewInterval').textContent=duration(c.interval_minutes);$('previewCount').textContent=p.blocks.length;$('previewBadge').className='tb-pill '+(p.valid?'ready':'issue');$('previewBadge').innerHTML=`<i class="fas ${p.valid?'fa-circle-check':'fa-triangle-exclamation'}"></i>${p.valid?'Validation passed':'Adjustment required'}`;$('previewIssues').innerHTML=(p.errors.length?`<div class="alert alert-danger mb-2"><strong><i class="fas fa-triangle-exclamation me-1"></i>Cannot save yet</strong><ul class="mb-0 mt-1">${p.errors.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></div>`:'')+(p.warnings.length?`<div class="alert alert-warning mb-2"><strong><i class="fas fa-circle-info me-1"></i>Review note</strong><ul class="mb-0 mt-1">${p.warnings.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></div>`:'');$('previewBody').innerHTML=p.blocks.length?p.blocks.map((b,i)=>`<tr><td>${i+1}</td><td class="tb-code">${esc(b.code)}</td><td>${fmtTime(b.start_time)}</td><td>${fmtTime(b.end_time)}</td><td>${duration(b.duration_minutes)}</td><td>${catPill(b.block_type==='Exam'?'Exam-specific':b.block_type)}</td><td><span class="tb-pill ${b.status==='Ready'?'ready':'issue'}"><i class="fas ${b.status==='Ready'?'fa-check':'fa-xmark'}"></i>${esc(b.status)}</span>${b.issues.length?`<div class="small text-danger mt-1">${esc(b.issues.join(' '))}</div>`:''}</td></tr>`).join(''):'<tr><td colspan="7" class="tb-empty">No blocks generated.</td></tr>';$('saveSet').disabled=!p.valid;}
async function generate(){try{const payload=setPayload('preview_set'),d=await req(payload);state.preview=d.preview;state.previewPayload=payload;renderPreview();go('preview');}catch(e){alertMsg(e.message,'danger');}}
async function saveSet(){if(!state.preview||!state.preview.valid)return;const btn=$('saveSet'),old=btn.innerHTML;btn.disabled=true;btn.innerHTML='<i class="fas fa-spinner fa-spin me-1"></i>Rechecking & Saving...';try{const d=await req({...state.previewPayload,action:'save_set'});state.lastSet=d.set;$('confirmRef').textContent=d.set.reference_no;$('confirmName').textContent=d.set.name;$('confirmCount').textContent=d.set.block_count;$('confirmStatus').textContent=d.set.status;await load();go('confirmation');}catch(e){alertMsg(e.message,'danger');}finally{btn.disabled=false;btn.innerHTML=old;}}
function editBlock(id){const b=state.blocks.find(x=>Number(x.id)===Number(id));if(!b)return;$('editId').value=b.id;$('singleCode').value=b.code;$('singleLabel').value=b.label;$('singleStart').value=b.start_time.slice(0,5);$('singleEnd').value=b.end_time.slice(0,5);$('singleType').value=b.block_type;$('singleActive').checked=Number(b.is_active)===1;$('singleTitle').textContent='Edit Time Block · '+b.code;$('singleValidation').className='tb-note';$('singleValidation').innerHTML='<i class="fas fa-circle-info me-1"></i>Run validation after making changes.';updateDuration();go('single');}
async function toggleBlock(id){const b=state.blocks.find(x=>Number(x.id)===Number(id));if(!b)return;const verb=Number(b.is_active)===1?'deactivate':'activate';if(!confirm(`Are you sure you want to ${verb} ${b.code}?${Number(b.usage_count)>0?' It is referenced by '+b.usage_count+' schedule record(s).':''}`))return;try{const d=await req({action:'toggle',id:Number(id)});alertMsg(d.message,'success');await load();}catch(e){alertMsg(e.message,'danger');}}
async function deleteBlock(id){const b=state.blocks.find(x=>Number(x.id)===Number(id));if(!b||!confirm(`Delete unused block ${b.code}? This removes the block but retains its audit event.`))return;try{const d=await req({action:'delete',id:Number(id)});alertMsg(d.message,'success');await load();}catch(e){alertMsg(e.message,'danger');}}
function bindRowActions(root){root.querySelectorAll('[data-edit]').forEach(x=>x.onclick=()=>editBlock(x.dataset.edit));root.querySelectorAll('[data-toggle]').forEach(x=>x.onclick=()=>toggleBlock(x.dataset.toggle));root.querySelectorAll('[data-delete]').forEach(x=>x.onclick=()=>deleteBlock(x.dataset.delete));}
function exportCsv(){const rows=[['Code','Label','Start','End','Duration Minutes','Type','Category','Status','Usage','Set'],...state.blocks.map(b=>[b.code,b.label,b.start_time,b.end_time,b.duration_minutes,b.block_type,b.category,Number(b.is_active)===1?'Active':'Inactive',b.usage_count,b.set_reference||'Manual'])];const csv=rows.map(r=>r.map(v=>'"'+String(v??'').replace(/"/g,'""')+'"').join(',')).join('\r\n'),a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv'}));a.download='time-blocks-'+new Date().toISOString().slice(0,10)+'.csv';a.click();URL.revokeObjectURL(a.href);}
document.addEventListener('DOMContentLoaded',()=>{document.querySelectorAll('[data-go]').forEach(x=>x.addEventListener('click',()=>go(x.dataset.go)));document.querySelectorAll('.tb-step').forEach(x=>x.addEventListener('click',()=>go(x.dataset.screen)));['dashSearch','dashType','dashStatus'].forEach(id=>$(id).addEventListener('input',renderDashboard));['manageSearch','manageCategory','manageStatus'].forEach(id=>$(id).addEventListener('input',renderManage));['singleStart','singleEnd'].forEach(id=>$(id).addEventListener('input',updateDuration));$('includeBreak').addEventListener('change',()=>{$('breakFields').classList.toggle('opacity-50',!$('includeBreak').checked);$('breakFields').querySelectorAll('input').forEach(x=>x.disabled=!$('includeBreak').checked);});$('validateSingle').onclick=validateSingle;$('saveSingle').onclick=saveSingle;$('generatePreview').onclick=generate;$('saveSet').onclick=saveSet;$('openHistory').onclick=renderHistory;$('manageHistory').onclick=renderHistory;$('dashExport').onclick=exportCsv;$('manageExport').onclick=exportCsv;$('dashPrint').onclick=()=>window.print();load();});
})();
</script>
<?php require_once __DIR__ . '/../../../includes/layout-end.php'; ?>
